<?php
namespace Tests\Feature;
use App\Models\User;
use App\Modules\Tenancy\Models\Officine;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Laravel\Sanctum\Sanctum;
use Tests\TestCase;
class AccessOperationsTest extends TestCase {
 use RefreshDatabase;
 private User $u;private Officine $o;private Officine $foreign;
 protected function setUp():void{parent::setUp();$this->u=User::create(['name'=>'Fictif','email'=>'user@example.test','password'=>'Fictional12345']);$this->o=Officine::create(['name'=>'Locale','slug'=>'locale','status'=>'active']);$this->foreign=Officine::create(['name'=>'Etrangère','slug'=>'etrangere','status'=>'active']);DB::table('officine_user')->insert(['user_id'=>$this->u->id,'officine_id'=>$this->o->id,'is_active'=>true,'is_admin'=>true,'permissions'=>'[]','created_at'=>now()]);Sanctum::actingAs($this->u);$this->withHeader('X-Officine-ID',(string)$this->o->id);}
 private function audit(int $office,string $action='team.role.saved'):void{DB::table('tenant_audit_logs')->insert(['officine_id'=>$office,'user_id'=>$this->u->id,'action'=>$action,'payload'=>json_encode(['role_id'=>1,'token'=>'secret-token','password'=>'secret-password','before'=>['name'=>'Lecture','password'=>'nested-secret'],'after'=>['permissions'=>['qualite.read']]]),'created_at'=>now(),'updated_at'=>now()]);}
 public function test_journal_is_scoped_paginated_filterable_and_redacts_secrets():void{for($i=0;$i<27;$i++)$this->audit($this->o->id);$this->audit($this->foreign->id);$r=$this->getJson('/api/v1/officine/journal?action=team.role.saved')->assertOk()->assertJsonPath('total',27)->assertJsonCount(25,'data')->assertJsonPath('last_page',2);$this->assertStringNotContainsString('secret',$r->getContent());$this->getJson('/api/v1/officine/journal?page=2')->assertJsonCount(2,'data');$this->getJson('/api/v1/officine/journal?to='.now()->toDateString())->assertOk();$this->getJson('/api/v1/officine/journal?from=2026-11-11&to=2026-11-10')->assertUnprocessable();$this->getJson('/api/v1/officine/journal?action=no-event')->assertJsonPath('total',0);}
 public function test_non_admin_cannot_read_journal_or_summary_and_platform_cannot_read_tenant_business():void{$this->getJson('/api/v1/platform/journal')->assertForbidden();DB::table('officine_user')->where('user_id',$this->u->id)->update(['is_admin'=>false]);$this->getJson('/api/v1/officine/journal')->assertForbidden();$this->getJson('/api/v1/officine/summary')->assertForbidden();$this->u->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($this->u);$this->audit($this->o->id,'application.draft.created');$this->audit($this->o->id,'account.state');$this->audit($this->o->id,'team.role.saved');$this->getJson('/api/v1/platform/journal')->assertOk()->assertJsonCount(1,'data')->assertJsonPath('data.0.action','account.state');}
 public function test_dashboard_counts_only_authorized_data_and_excludes_expired_invites():void{foreach([[$this->o->id,now()->addDay()],[$this->o->id,now()->subDay()],[$this->foreign->id,now()->addDay()]] as [$office,$expiry])DB::table('officine_invitations')->insert(['officine_id'=>$office,'email'=>'fictif@example.test','token'=>hash('sha256',random_bytes(20)),'roles'=>'{}','expires_at'=>$expiry,'created_at'=>now(),'updated_at'=>now()]);$this->getJson('/api/v1/officine/summary?days=7')->assertOk()->assertJsonPath('scope','officine')->assertJsonPath('counts.members_active',1)->assertJsonPath('counts.invitations_pending',1)->assertJsonPath('period.days',7);$this->getJson('/api/v1/officine/summary?days=999')->assertUnprocessable();$this->u->forceFill(['is_platform_admin'=>true])->save();Sanctum::actingAs($this->u);$this->getJson('/api/v1/platform/summary')->assertOk()->assertJsonPath('counts.active',2)->assertJsonPath('counts.invitations_pending',2);}
 public function test_notifications_are_paginated_filtered_owner_scoped_and_retry_bounded():void{for($i=0;$i<27;$i++)Outbox::push($this->u->id,'event-'.$i,'Test','Contenu secret');$id=DB::table('notification_outbox')->value('id');DB::table('notification_outbox')->where('id',$id)->update(['status'=>'failed','attempts'=>4]);$this->getJson('/api/v1/notifications')->assertOk()->assertJsonPath('total',27)->assertJsonCount(25,'data');$this->getJson('/api/v1/notifications?status=failed')->assertJsonCount(1,'data');$this->postJson('/api/v1/notifications/'.$id.'/retry')->assertOk();DB::table('notification_outbox')->where('id',$id)->update(['attempts'=>5]);$this->postJson('/api/v1/notifications/'.$id.'/retry')->assertConflict();$other=User::create(['name'=>'Autre','email'=>'other@example.test','password'=>'Fictional12345']);Sanctum::actingAs($other);$this->postJson('/api/v1/notifications/'.$id.'/retry')->assertNotFound();$this->postJson('/api/v1/notifications/'.$id.'/read')->assertNotFound();$this->getJson('/api/v1/notifications')->assertJsonCount(0,'data');}
 public function test_profile_locale_is_versioned_and_cannot_change_identity():void{$this->putJson('/api/v1/me',['name'=>'Fictif','phone'=>null,'locale'=>'en','profile_version'=>1,'is_platform_admin'=>true])->assertOk()->assertJsonPath('user.locale','en');$this->assertFalse($this->u->fresh()->is_platform_admin);$this->putJson('/api/v1/me',['name'=>'Fictif','locale'=>'zz','profile_version'=>2])->assertUnprocessable();}
}
